"""Lexer -> AST -> scope/type checking -> portable C11 generation."""

from dataclasses import dataclass, field
from pathlib import Path
import re

from .numbers import decode_number
from . import __version__


KEYWORDS = {
    "우사기!": "MAIN", "!우사기": "MAIN_END",
    "우나!": "FUNCTION", "우~나!": "RETURN", "야하!": "END",
    "우랏!": "OPEN", "우라랏!": "CLOSE",
    "우라!": "LPAREN", "우라라!": "RPAREN",
    "얏!": "INT", "핫!": "REAL", "얏핫!": "CHAR", "하치와레!": "STRING", "야얏!": "INT_ARRAY",
    "얏하핫!": "OLD_STRING", "하치와레:": "NAME_PREFIX",
    "하치!": "STRING_OPEN", "와레!": "STRING_CLOSE",
    "야~하!": "ASSIGN", "하!": "ADD", "하아!": "SUB",
    "하핫!": "MUL", "푸루!": "DIV", "푸루루!": "MOD",
    "하아?": "INPUT", "냠?": "NUMBER_INPUT", "우~라~": "OUTPUT",
    ",": "COMMA", "우이!": "NEWLINE",
    "갸웃?": "SIGN", "갸웃!": "SIGN_END",
    "야호!": "POSITIVE", "하아...": "ZERO", "우우...": "NEGATIVE",
    "우쨔?": "COUNT", "우쨔!": "COUNT_END", "뿌야!": "REMAINING",
    "푸루룻!": "REPEAT", "푸루룻?": "REPEAT_TEST",
    "삐익!": "BREAK", "휙!": "CONTINUE",
    "냠!": "FEED", "꿀꺽!": "SWALLOW",
    "우~라!": "WRITE", "시사!": "CONCAT", "모몽가!": "STRINGIFY",
}

REACTIONS = {"POSITIVE", "ZERO", "NEGATIVE"}
CLOSERS = {"MAIN_END", "RETURN", "CLOSE", "SIGN_END", "COUNT_END", "REPEAT_TEST"}


@dataclass(frozen=True)
class Token:
    kind: str
    text: str
    line: int
    column: int


class CompileError(Exception):
    def __init__(self, token: Token, message: str):
        self.token = token
        self.message = message
        super().__init__(message)

    def format(self, path: str, source: str) -> str:
        lines = source.splitlines()
        line = lines[self.token.line - 1] if self.token.line <= len(lines) else ""
        # Preserve tabs so the caret tracks the source in terminals.
        padding = "".join("\t" if c == "\t" else " " for c in line[:self.token.column - 1])
        return f"{path}:{self.token.line}:{self.token.column}: 오류: {self.message}\n  {line}\n  {padding}^"


def lex(source: str) -> list[Token]:
    tokens: list[Token] = []
    lines = source.splitlines()
    for line_number, line in enumerate(lines, 1):
        position = 0
        while position < len(line):
            if line[position].isspace():
                position += 1
                continue
            start = position
            if line.startswith("하치!", position):
                end = line.find("와레!", position + 3)
                token = Token("TEXT", "", line_number, start + 1)
                if end < 0:
                    raise CompileError(token, "문자열을 닫는 와레!가 같은 줄에 필요합니다.")
                text = line[position + 3:end]
                # One adjacent ASCII space on each side is syntax padding.
                text = text.removeprefix(" ").removesuffix(" ").replace("우이!", "\n")
                if "\0" in text or len(text.encode("utf-8")) > 4095:
                    raise CompileError(token, "문자열은 NUL 없이 UTF-8 4095바이트까지 지원합니다.")
                position = end + 3
                if position < len(line) and not line[position].isspace():
                    raise CompileError(token, "와레! 뒤의 문법 토큰은 공백으로 구분하세요.")
                tokens.append(Token("TEXT", text, line_number, start + 1))
                continue
            match = re.match(r"[^\s,]+|,", line[position:])
            text = match.group()
            position += len(text)
            if text == "하치와레:":
                words = []
                while position < len(line):
                    next_match = re.match(r"\s*([^\s,]+)", line[position:])
                    if next_match is None:
                        break
                    word = next_match.group(1)
                    if (word in KEYWORDS or re.fullmatch(r"[뿌르릇~.]+", word) or word.startswith("하치!")
                            or (words and re.fullmatch(r"야+", word))):
                        break
                    pattern = r"[A-Za-z가-힣_][A-Za-z가-힣_0-9]*" if not words else r"[A-Za-z가-힣_0-9]+"
                    if not re.fullmatch(pattern, word):
                        raise CompileError(Token("INVALID", word, line_number, position + 1),
                                           "이름에는 한글·영문·숫자·밑줄과 단어 사이 공백을 사용하세요. 숫자로 시작할 수 없습니다.")
                    words.append(word)
                    position += next_match.end()
                if not words:
                    raise CompileError(Token("NAME", "", line_number, start + 1),
                                       "하치와레: 뒤 같은 줄에 사용자 이름이 필요합니다.")
                tokens.append(Token("NAME", " ".join(words), line_number, start + 1))
                continue
            kind = KEYWORDS.get(text)
            if kind is None:
                if re.fullmatch(r"야+", text):
                    kind = "SHORT_NAME"
                elif re.fullmatch(r"[뿌르릇~.]+", text):
                    kind = "NUMBER"
                else:
                    token = Token("INVALID", text, line_number, start + 1)
                    raise CompileError(token, f"알 수 없는 토큰 {text!r}. 야 반복 변수명 외의 사용자 이름 앞에는 하치와레:를 붙이고 토큰은 공백으로 구분하세요.")
            if kind == "OLD_STRING":
                raise CompileError(Token(kind, text, line_number, start + 1), "문자열형 얏하핫!은 하치와레!로 바뀌었습니다.")
            if kind == "STRING_CLOSE":
                raise CompileError(Token(kind, text, line_number, start + 1), "문자열 시작 하치! 없이 와레!를 사용할 수 없습니다.")
            if kind == "NEWLINE":
                raise CompileError(Token(kind, text, line_number, start + 1), "우이!는 하치! … 와레! 문자열 안의 개행 표기입니다.")
            tokens.append(Token(kind, text, line_number, start + 1))
    eof_line = len(lines) + 1 if source.endswith(("\n", "\r")) else max(1, len(lines))
    eof_column = 1 if not lines or source.endswith(("\n", "\r")) else len(lines[-1]) + 1
    tokens.append(Token("EOF", "", eof_line, eof_column))
    return tokens


@dataclass
class Expr:
    token: Token
    kind: str
    value: str = ""
    left: "Expr | None" = None
    right: "Expr | None" = None
    type: str = ""
    binding: str = ""
    args: list["Expr"] = field(default_factory=list)
    arg_types: list[str] = field(default_factory=list)


@dataclass
class Statement:
    token: Token
    kind: str
    name: Token | None = None
    expr: Expr | None = None
    body: list["Statement"] = field(default_factory=list)
    type: str = ""
    binding: str = ""
    branches: list["Branch"] = field(default_factory=list)
    needs_continue: bool = False
    target: Expr | None = None
    targets: list[Expr] = field(default_factory=list)
    newline: bool = True


@dataclass
class Branch:
    token: Token
    body: list[Statement]


@dataclass
class Function:
    token: Token
    name: str
    body: list[Statement]
    result: Expr | None = None
    type: str = ""
    binding: str = ""
    params: list["Parameter"] = field(default_factory=list)


@dataclass
class Parameter:
    name: Token
    type: str
    binding: str = ""


@dataclass
class Program:
    functions: list[Function]
    main: Function


class Parser:
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.index = 0

    @property
    def current(self) -> Token:
        return self.tokens[self.index]

    def take(self) -> Token:
        token = self.current
        self.index += 1
        return token

    def expect(self, kind: str, message: str) -> Token:
        if self.current.kind != kind:
            raise CompileError(self.current, message)
        return self.take()

    def variable_name(self) -> Token:
        if self.current.kind not in ("NAME", "SHORT_NAME"):
            raise CompileError(self.current, "변수 이름은 야 반복 이름 또는 하치와레: 이름으로 작성하세요.")
        return self.take()

    def parse(self) -> Program:
        functions = []
        main = None
        while self.current.kind != "EOF":
            token = self.take()
            if token.kind == "MAIN":
                if main is not None:
                    raise CompileError(token, "우사기! 메인은 하나만 선언할 수 있습니다.")
                body = self.statements("MAIN_END")
                self.expect("MAIN_END", "메인을 닫고 0을 반환하는 !우사기가 필요합니다.")
                main = Function(token, "우사기!", body, type="int", binding="main")
            elif token.kind == "FUNCTION":
                name = self.current
                if name.kind != "NAME":
                    raise CompileError(name, "우나! 뒤에는 하치와레: 함수명이 필요합니다. 메인은 우사기!로 시작하세요.")
                self.take()
                params = []
                while self.current.kind == "FEED":
                    self.take()
                    parameter_type = self.current
                    if parameter_type.kind not in ("INT", "REAL", "STRING"):
                        raise CompileError(parameter_type, "선언의 냠! 뒤에는 얏!, 핫!, 하치와레! 자료형과 매개변수 이름이 필요합니다.")
                    self.take()
                    params.append(Parameter(self.variable_name(), {"INT": "int", "REAL": "real", "STRING": "string"}[parameter_type.kind]))
                body = self.statements("RETURN")
                self.expect("RETURN", "함수를 닫는 우~나! 반환값이 필요합니다.")
                result = self.expression()
                functions.append(Function(name, name.text, body, result, params=params))
            else:
                raise CompileError(token, "최상위에는 우사기! 메인 또는 우나! 함수 선언만 올 수 있습니다.")
            # Closing markers already delimit the function; a trailing END is optional.
            if self.current.kind == "END":
                self.take()
        if main is None:
            raise CompileError(self.current, "우사기! … !우사기 메인이 필요합니다.")
        return Program(functions, main)

    def statements(self, until: str | set[str]) -> list[Statement]:
        stops = {until} if isinstance(until, str) else until
        closing = {"MAIN_END": "!우사기", "RETURN": "우~나! 반환값", "CLOSE": "우라랏!",
                   "SIGN_END": "갸웃!", "COUNT_END": "우쨔!", "REPEAT_TEST": "푸루룻? 조건식"}
        expected = next((closing[k] for k in closing if k in stops), "닫는 표식")
        body = []
        while self.current.kind not in stops | {"EOF"}:
            if self.current.kind in CLOSERS | REACTIONS | {"FUNCTION", "MAIN"}:
                raise CompileError(self.current, f"현재 본문을 닫는 {expected}가 필요합니다. 함수는 중첩 선언할 수 없습니다.")
            body.append(self.statement())
        return body

    def optional_end(self) -> None:
        if self.current.kind == "END":
            self.take()

    def sign_statement(self, token: Token) -> Statement:
        value = self.expression()
        branches = []
        seen = set()
        while self.current.kind in REACTIONS:
            reaction = self.take()
            if reaction.kind in seen:
                raise CompileError(reaction, f"{reaction.text} 반응을 중복해서 작성할 수 없습니다.")
            seen.add(reaction.kind)
            branches.append(Branch(reaction, self.statements(REACTIONS | {"SIGN_END"})))
        if not branches:
            raise CompileError(self.current, "갸웃? 뒤에는 야호!, 하아..., 우우... 반응이 적어도 하나 필요합니다.")
        self.expect("SIGN_END", "분기를 닫는 갸웃!이 필요합니다.")
        self.optional_end()
        return Statement(token, "sign", expr=value, branches=branches)

    def block(self) -> list[Statement]:
        self.expect("OPEN", "블록은 우랏!으로 시작합니다.")
        body = self.statements("CLOSE")
        self.expect("CLOSE", "블록을 닫는 우라랏!이 필요합니다.")
        return body

    def statement(self) -> Statement:
        token = self.current
        if token.kind == "OPEN":
            return Statement(token, "block", body=self.block())
        self.take()
        if token.kind == "SIGN":
            return self.sign_statement(token)
        if token.kind == "COUNT":
            value = self.expression()
            body = self.statements("COUNT_END")
            self.expect("COUNT_END", "횟수 반복을 닫는 우쨔!가 필요합니다.")
            self.optional_end()
            return Statement(token, "count", expr=value, body=body)
        if token.kind == "REPEAT":
            body = self.statements("REPEAT_TEST")
            self.expect("REPEAT_TEST", "조건 반복을 닫는 푸루룻? 조건식이 필요합니다.")
            value = self.expression()
            self.optional_end()
            return Statement(token, "repeat", expr=value, body=body)
        if token.kind == "CHAR":
            raise CompileError(token, "문자형 리터럴 문법은 아직 미정이며 현재 버전에서는 지원하지 않습니다.")
        if token.kind in ("INT", "REAL", "STRING"):
            name = self.variable_name()
            result = Statement(token, "declare", name, self.expression(), type={"INT": "int", "REAL": "real", "STRING": "string"}[token.kind])
        elif token.kind == "INT_ARRAY":
            size = self.expression(indexing=False)
            result = Statement(token, "array_declare", self.variable_name(), size, type="int_array")
        elif token.kind == "INPUT":
            result = Statement(token, "input", target=self.expression())
        elif token.kind == "NUMBER_INPUT":
            targets = [self.expression()]
            while self.current.kind == "COMMA":
                self.take()
                targets.append(self.expression())
            result = Statement(token, "number_input", targets=targets)
        elif token.kind in ("OUTPUT", "WRITE"):
            result = Statement(token, "output", expr=self.expression(), newline=token.kind == "OUTPUT")
        elif token.kind in ("BREAK", "CONTINUE"):
            result = Statement(token, token.kind.lower())
        elif token.kind in ("NAME", "SHORT_NAME", "NUMBER", "LPAREN", "REMAINING"):
            self.index -= 1
            target = self.expression(assignment_target=True)
            if target.kind == "call" and self.current.kind == "END":
                result = Statement(token, "call", expr=target)
            else:
                self.expect("ASSIGN", "변수나 배열 원소에 대입하려면 야~하!를 사용하세요.")
                result = Statement(token, "assign", expr=self.expression(), target=target)
        else:
            raise CompileError(token, "선언, 대입, 입출력, 블록, 제어문 또는 함수 호출문이 필요합니다.")
        self.expect("END", "문장 끝에 야하!가 필요합니다.")
        return result

    def call(self, name: Token) -> Expr:
        if name.kind != "NAME":
            raise CompileError(name, "함수 이름에는 항상 하치와레:가 필요합니다. 야 반복 예외는 변수에만 적용합니다.")
        if self.current.kind == "LPAREN":
            self.take()
            self.expect("RPAREN", "괄호 호출은 인자 없을 때만 사용합니다. 값은 냠! 값 … 꿀꺽!으로 넘기세요.")
            return Expr(name, "call", name.text)
        args = []
        while self.current.kind == "FEED":
            self.take()
            args.append(self.expression())
        self.expect("SWALLOW", "먹이기 호출을 끝내는 꿀꺽!이 필요합니다.")
        return Expr(name, "call", name.text, args=args)

    def expression(self, minimum: int = 0, indexing: bool = True, assignment_target: bool = False) -> Expr:
        token = self.take()
        if token.kind == "NUMBER":
            try:
                number_type, spelling = decode_number(token.text)
            except ValueError as error:
                raise CompileError(token, str(error)) from error
            left = Expr(token, "literal", spelling, type=number_type)
        elif token.kind == "TEXT":
            left = Expr(token, "literal", token.text, type="string")
        elif token.kind == "REMAINING":
            left = Expr(token, "remaining", type="int")
        elif token.kind in ("NAME", "SHORT_NAME"):
            if self.current.kind in ("LPAREN", "FEED"):
                left = self.call(token)
            else:
                left = Expr(token, "variable", token.text)
        elif token.kind == "STRINGIFY":
            self.expect("LPAREN", "모몽가! 뒤에는 우라! 숫자식 우라라!가 필요합니다.")
            left = Expr(token, "stringify", left=self.expression(), type="string")
            self.expect("RPAREN", "모몽가!의 숫자식을 닫는 우라라!가 필요합니다.")
        elif token.kind == "LPAREN":
            left = self.expression()
            self.expect("RPAREN", "괄호를 닫는 우라라!가 필요합니다.")
        else:
            raise CompileError(token, "숫자, 문자열, 하치와레: 이름 또는 우라! … 우라라! 식이 필요합니다.")
        while indexing and self.current.kind in ("NAME", "SHORT_NAME"):
            # A following assignment/call can be the first statement of a loop
            # body; its variable/function name is not part of the condition.
            following = self.tokens[self.index + 1].kind
            if following in ("LPAREN", "FEED") or (following == "ASSIGN" and not assignment_target):
                break
            name = self.take()
            left = Expr(name, "index", name.text, left=left, type="int")
        precedence = {"CONCAT": 0, "ADD": 1, "SUB": 1, "MUL": 2, "DIV": 2, "MOD": 2}
        while precedence.get(self.current.kind, -1) >= minimum:
            operator = self.take()
            right = self.expression(precedence[operator.kind] + 1, indexing=indexing)
            left = Expr(operator, "binary", operator.kind, left, right)
        return left


def analyze(program: Program) -> None:
    functions: dict[str, Function] = {}
    states: dict[str, str] = {}
    counter = 0
    for index, function in enumerate(program.functions, 1):
        if function.name in functions:
            raise CompileError(function.token, f"함수 {function.name!r}를 중복 선언했습니다.")
        function.binding = f"us_f{index}"
        functions[function.name] = function

    def analyze_function(function: Function) -> None:
        if states.get(function.name) == "done":
            return
        states[function.name] = "visiting"
        scopes: list[dict[str, tuple[str, str]]] = [{}]
        loops: list[Statement] = []
        counted_loops: list[Statement] = []
        nonlocal counter
        for parameter in function.params:
            if parameter.name.text in scopes[0]:
                raise CompileError(parameter.name, "같은 이름의 매개변수를 중복 선언할 수 없습니다.")
            counter += 1
            parameter.binding = f"us_v{counter}"
            scopes[0][parameter.name.text] = (parameter.type, parameter.binding)

        def lookup(token: Token) -> tuple[str, str]:
            for scope in reversed(scopes):
                if token.text in scope:
                    return scope[token.text]
            raise CompileError(token, f"선언되지 않은 변수 {token.text!r}입니다.")

        def expression(expr: Expr) -> str:
            if expr.kind == "variable":
                expr.type, expr.binding = lookup(expr.token)
            elif expr.kind == "index":
                if expression(expr.left) != "int":
                    raise CompileError(expr.left.token, "배열 인덱스는 정수여야 합니다.")
                array_type, expr.binding = lookup(expr.token)
                if array_type != "int_array":
                    raise CompileError(expr.token, "인덱스 뒤의 변수는 야얏! 정수 배열이어야 합니다.")
            elif expr.kind == "remaining":
                if not counted_loops:
                    raise CompileError(expr.token, "뿌야!는 같은 함수의 우쨔? 횟수 반복 안에서만 사용할 수 있습니다.")
                expr.binding = counted_loops[-1].binding
            elif expr.kind == "call":
                callee = functions.get(expr.value)
                if callee is None:
                    raise CompileError(expr.token, f"선언되지 않은 함수 {expr.value!r}입니다.")
                if len(expr.args) != len(callee.params):
                    raise CompileError(expr.token, f"함수 {expr.value!r}는 인자 {len(callee.params)}개가 필요하지만 {len(expr.args)}개를 받았습니다.")
                if states.get(callee.name) == "visiting":
                    raise CompileError(expr.token, "재귀·순환 호출은 현재 지원하지 않습니다. 반환형 추론에 순환이 있습니다.")
                analyze_function(callee)
                for argument, parameter in zip(expr.args, callee.params):
                    assignable(parameter.type, argument)
                expr.arg_types = [p.type for p in callee.params]
                expr.type, expr.binding = callee.type, callee.binding
            elif expr.kind == "stringify":
                if expression(expr.left) not in ("int", "real"):
                    raise CompileError(expr.token, "모몽가!는 정수 또는 실수만 문자열로 변환합니다.")
            elif expr.kind == "binary":
                left, right = expression(expr.left), expression(expr.right)
                if expr.value == "CONCAT":
                    if (left, right) != ("string", "string"):
                        raise CompileError(expr.token, "시사!는 문자열끼리 연결합니다. 숫자는 모몽가!로 변환하세요.")
                    expr.type = "string"
                    return expr.type
                if "int_array" in (left, right):
                    raise CompileError(expr.token, "배열 전체로 계산할 수 없습니다. 인덱스로 원소를 선택하세요.")
                if "string" in (left, right):
                    raise CompileError(expr.token, "문자열 산술은 지원하지 않습니다. 연결에는 시사!를 사용하세요.")
                if expr.value == "MOD" and (left != "int" or right != "int"):
                    raise CompileError(expr.token, "푸루루! 나머지 연산은 정수끼리만 사용할 수 있습니다.")
                expr.type = "real" if "real" in (left, right) else "int"
            return expr.type

        def assignable(target: str, expr: Expr) -> None:
            actual = expression(expr)
            if "int_array" in (target, actual):
                raise CompileError(expr.token, "배열 전체의 복사·대입·인자 전달은 지원하지 않습니다. 원소를 선택하세요.")
            if (target == "string") != (actual == "string"):
                raise CompileError(expr.token, "문자열과 숫자 사이의 자동 변환은 아직 지원하지 않습니다.")

        def nested(statements: list[Statement]) -> None:
            scopes.append({})
            visit(statements)
            scopes.pop()

        def numeric(expr: Expr) -> str:
            actual = expression(expr)
            if actual not in ("int", "real"):
                raise CompileError(expr.token, "분기·반복 조건은 정수 또는 실수여야 합니다.")
            return actual

        def lvalue(expr: Expr) -> str:
            if expr.kind == "remaining":
                raise CompileError(expr.token, "뿌야!는 읽기 전용 남은 횟수이며 대입하거나 입력받을 수 없습니다.")
            if expr.kind not in ("variable", "index"):
                raise CompileError(expr.token, "입력·대입 대상은 선언된 변수 또는 배열 원소여야 합니다.")
            actual = expression(expr)
            if actual == "int_array":
                raise CompileError(expr.token, "배열 전체에는 입력·대입할 수 없습니다. 인덱스로 원소를 선택하세요.")
            return actual

        def visit(statements: list[Statement]) -> None:
            nonlocal counter
            for statement in statements:
                if statement.kind == "block":
                    nested(statement.body)
                elif statement.kind == "sign":
                    numeric(statement.expr)
                    for branch in statement.branches:
                        nested(branch.body)
                elif statement.kind in ("count", "repeat"):
                    actual = numeric(statement.expr)
                    if statement.kind == "count" and actual != "int":
                        raise CompileError(statement.expr.token, "우쨔? 반복 횟수는 정수여야 합니다. 실수는 자동 변환하지 않습니다.")
                    counter += 1
                    statement.binding = f"us_loop{counter}"
                    loops.append(statement)
                    if statement.kind == "count":
                        counted_loops.append(statement)
                    nested(statement.body)
                    if statement.kind == "count":
                        counted_loops.pop()
                    loops.pop()
                elif statement.kind in ("break", "continue"):
                    if not loops:
                        raise CompileError(statement.token, f"{statement.token.text}는 같은 함수의 반복문 안에서만 사용할 수 있습니다.")
                    if statement.kind == "continue" and loops[-1].kind == "repeat":
                        loops[-1].needs_continue = True
                        statement.binding = loops[-1].binding
                elif statement.kind in ("declare", "array_declare"):
                    if statement.name.text in scopes[-1]:
                        raise CompileError(statement.name, "같은 블록에서 변수를 중복 선언할 수 없습니다.")
                    if statement.kind == "array_declare":
                        if expression(statement.expr) != "int":
                            raise CompileError(statement.expr.token, "배열 크기는 정수여야 합니다.")
                    else:
                        assignable(statement.type, statement.expr)
                    counter += 1
                    statement.binding = f"us_v{counter}"
                    scopes[-1][statement.name.text] = (statement.type, statement.binding)
                elif statement.kind in ("assign", "input"):
                    statement.type = lvalue(statement.target)
                    if statement.kind == "input" and statement.type != "string":
                        raise CompileError(statement.target.token, "하아?는 문자열 입력입니다. 정수·실수 입력에는 냠?을 사용하세요.")
                    if statement.kind == "assign":
                        assignable(statement.type, statement.expr)
                elif statement.kind == "number_input":
                    for target in statement.targets:
                        if lvalue(target) not in ("int", "real"):
                            raise CompileError(target.token, "냠?는 숫자 입력입니다. 문자열 입력에는 하아?를 사용하세요.")
                elif statement.kind in ("output", "call"):
                    if expression(statement.expr) == "int_array":
                        raise CompileError(statement.expr.token, "배열 전체를 출력할 수 없습니다. 원소를 선택하세요.")

        visit(function.body)
        if function.result is not None:
            function.type = expression(function.result)
            if function.type == "int_array":
                raise CompileError(function.result.token, "배열 전체를 반환할 수 없습니다. 원소를 반환하세요.")
        states[function.name] = "done"

    for function in program.functions:
        analyze_function(function)
    analyze_function(program.main)


def c_string(text: str) -> str:
    # Fixed-width octal escapes prevent quote, backslash, trigraph and UTF-8 ambiguity.
    return '"' + "".join(f"\\{byte:03o}" for byte in text.encode("utf-8")) + '"'


def generate_c(program: Program, path: str) -> str:
    runtime = Path(__file__).with_name("runtime.c").read_text(encoding="utf-8")
    output = [f"/* Generated by Usagi {__version__}. Self-contained C11. */", runtime,
              f"const char *us_source = {c_string(path)};"]
    counter = 0
    depth = 1
    ctype = {"int": "int64_t", "real": "double", "string": "us_string", "int_array": "us_array *"}
    families = {"int": "i", "real": "r", "string": "s"}
    loop_marks: list[str] = []
    for function in program.functions:
        parameters = ", ".join(f"{ctype[p.type]} {p.binding}" for p in function.params) or "void"
        output.append(f"{ctype[function.type]} {function.binding}({parameters});")

    def emit(line: str) -> None:
        output.append("    " * depth + line)

    def converted(target: str, expr: Expr, value: str) -> str:
        if target == "real":
            return f"((double)({value}))"
        if target == "int" and expr.type == "real":
            return f"us_real_to_int({value}, {expr.token.line}, {expr.token.column})"
        return value

    def expression(expr: Expr) -> str:
        nonlocal counter
        if expr.kind == "literal":
            if expr.type == "string":
                return f"us_string_literal({c_string(expr.value)}, {expr.token.line}, {expr.token.column})"
            return f"((int64_t)({expr.value}))" if expr.type == "int" else expr.value
        if expr.kind in ("variable", "remaining"):
            return expr.binding
        if expr.kind == "index":
            address = lvalue(expr)
            counter += 1
            name = f"us_t{counter}"
            emit(f"int64_t {name} = {address};")
            return name
        if expr.kind == "call":
            arguments = []
            for argument, target in zip(expr.args, expr.arg_types):
                value = converted(target, argument, expression(argument))
                counter += 1
                argument_name = f"us_t{counter}"
                emit(f"{ctype[target]} {argument_name} = {value};")
                arguments.append(argument_name)
            counter += 1
            name = f"us_t{counter}"
            # Materialize each call before the next one: input/output order is defined.
            emit(f"{ctype[expr.type]} {name} = {expr.binding}({', '.join(arguments)});")
            return name
        if expr.kind == "stringify":
            value = expression(expr.left)
            counter += 1
            name = f"us_t{counter}"
            emit(f"us_string {name} = us_string_{families[expr.left.type]}({value}, {expr.token.line}, {expr.token.column});")
            return name
        left, right = expression(expr.left), expression(expr.right)
        counter += 1
        name = f"us_t{counter}"
        family = families[expr.type]
        if expr.type == "real":
            left, right = f"((double)({left}))", f"((double)({right}))"
        emit(f"{ctype[expr.type]} {name} = us_{family}_{expr.value.lower()}({left}, {right}, {expr.token.line}, {expr.token.column});")
        return name

    def lvalue(expr: Expr) -> str:
        nonlocal counter
        if expr.kind == "variable":
            return expr.binding
        index = expression(expr.left)
        counter += 1
        name = f"us_p{counter}"
        emit(f"int64_t *{name} = us_array_at({expr.binding}, {index}, {expr.token.line}, {expr.token.column});")
        return f"(*{name})"

    def scoped(statements: list[Statement], loop: bool = False) -> None:
        nonlocal counter
        counter += 1
        mark = f"us_mark{counter}"
        emit(f"us_array *{mark} = us_arrays;")
        if loop:
            loop_marks.append(mark)
        visit(statements)
        if loop:
            loop_marks.pop()
        emit(f"us_array_cleanup(&us_arrays, {mark});")

    def visit(statements: list[Statement]) -> None:
        nonlocal depth, counter
        for statement in statements:
            kind = statement.kind
            if kind == "block":
                emit("{")
                depth += 1
                scoped(statement.body)
                depth -= 1
                emit("}")
            elif kind == "sign":
                value = expression(statement.expr)
                counter += 1
                name = f"us_t{counter}"
                emit(f"{ctype[statement.expr.type]} {name} = {value};")
                for index, branch in enumerate(statement.branches):
                    comparison = {"POSITIVE": ">", "ZERO": "==", "NEGATIVE": "<"}[branch.token.kind]
                    emit(f"{'if' if index == 0 else 'else if'} ({name} {comparison} 0) {{")
                    depth += 1
                    scoped(branch.body)
                    depth -= 1
                    emit("}")
            elif kind == "count":
                # Freeze the count before entering the loop, including any outer counter.
                value = expression(statement.expr)
                emit("{")
                depth += 1
                name = statement.binding
                emit(f"int64_t {name} = us_count({value}, {statement.token.line}, {statement.token.column});")
                emit(f"for (; {name} > 0; --{name}) {{")
                depth += 1
                scoped(statement.body, loop=True)
                depth -= 1
                emit("}")
                depth -= 1
                emit("}")
            elif kind == "repeat":
                emit("while (1) {")
                depth += 1
                emit("{")
                depth += 1
                scoped(statement.body, loop=True)
                depth -= 1
                emit("}")
                if statement.needs_continue:
                    emit(f"{statement.binding}_test: ;")
                value = expression(statement.expr)
                emit(f"if (!(({value}) > 0)) break;")
                depth -= 1
                emit("}")
            elif kind == "break":
                emit(f"us_array_cleanup(&us_arrays, {loop_marks[-1]});")
                emit("break;")
            elif kind == "continue":
                emit(f"us_array_cleanup(&us_arrays, {loop_marks[-1]});")
                emit(f"goto {statement.binding}_test;" if statement.binding else "continue;")
            elif kind == "array_declare":
                value = expression(statement.expr)
                emit(f"us_array *{statement.binding} = us_array_new(&us_arrays, {value}, {statement.token.line}, {statement.token.column});")
                emit(f"(void){statement.binding};")
            elif kind in ("declare", "assign"):
                destination = statement.binding if kind == "declare" else lvalue(statement.target)
                value = expression(statement.expr)
                value = converted(statement.type, statement.expr, value)
                prefix = ctype[statement.type] + " " if kind == "declare" else ""
                emit(f"{prefix}{destination} = {value};")
                if kind == "declare":
                    emit(f"(void){statement.binding};")
            elif kind == "input":
                emit(f"{lvalue(statement.target)} = us_read_s({statement.token.line}, {statement.token.column});")
            elif kind == "number_input":
                for target in statement.targets:
                    destination = lvalue(target)
                    family = families[target.type]
                    emit(f"{destination} = us_read_{family}({target.token.line}, {target.token.column});")
            elif kind == "output":
                value = expression(statement.expr)
                family = families[statement.expr.type]
                operation = "print" if statement.newline else "write"
                emit(f"us_{operation}_{family}({value}, {statement.token.line}, {statement.token.column});")
            elif kind == "call":
                value = expression(statement.expr)
                emit(f"(void){value};")

    for function in [*program.functions, program.main]:
        return_type = "int" if function is program.main else ctype[function.type]
        parameters = ", ".join(f"{ctype[p.type]} {p.binding}" for p in function.params) or "void"
        output.append(f"{return_type} {function.binding}({parameters}) {{")
        emit("us_array *us_arrays = NULL;")
        for parameter in function.params:
            emit(f"(void){parameter.binding};")
        visit(function.body)
        value = expression(function.result) if function.result is not None else "0"
        if function is program.main:
            emit("us_array_cleanup(&us_arrays, NULL);")
            emit("return 0;")
        else:
            emit(f"{return_type} us_result = {value};")
            emit("us_array_cleanup(&us_arrays, NULL);")
            emit("return us_result;")
        output.append("}")
    return "\n".join(output) + "\n"


def compile_source(source: str, path: str = "<source>") -> str:
    tokens = lex(source)
    try:
        body = Parser(tokens).parse()
        analyze(body)
        return generate_c(body, path)
    except RecursionError as error:
        raise CompileError(tokens[0], "식 또는 블록이 너무 깊게 중첩되어 있습니다. 더 작은 식으로 나누세요.") from error

interpreter.py:
"""Bounded browser interpreter for the canonical Usagi v1.0 AST.

No user Python or generated native code is executed. The shared compiler owns
lexing, parsing, scopes and type checking; this module evaluates its typed AST.
"""
import json
import math
import re
import asyncio
from array import array
from decimal import Decimal, InvalidOperation
from usagi.compiler import Parser, lex, analyze, CompileError

MIN_INT, MAX_INT = -(2 ** 63), 2 ** 63 - 1
MAX_SOURCE, MAX_INPUT, MAX_OUTPUT = 262144, 1048576, 65536
MAX_ARRAY_ITEMS, MAX_STEPS = 1000000, 20000000
SPACE = " \t\r\n\v\f"


class RuntimeFailure(Exception):
    def __init__(self, token, message):
        self.token, self.message = token, message


class LoopBreak(Exception):
    pass


class LoopContinue(Exception):
    pass


class Input:
    def __init__(self, text, provider=None):
        self.text, self.position, self.pending = text, 0, ""
        self.provider = provider
        self.total_bytes = len(text.encode("utf-8"))

    async def line(self, token):
        if self.position == len(self.text):
            if self.provider is None:
                raise RuntimeFailure(token, "입력이 부족합니다.")
            value = await self.provider()
            if value is None:
                raise RuntimeFailure(token, "입력이 종료되었습니다 (EOF).")
            value = str(value)
            self.total_bytes += len(value.encode("utf-8")) + 1
            if self.total_bytes > MAX_INPUT:
                raise RuntimeFailure(token, "입력이 웹 실행기의 1 MiB 한도를 초과했습니다.")
        else:
            end = self.text.find("\n", self.position)
            if end < 0:
                end = len(self.text)
            value = self.text[self.position:end]
            self.position = min(end + 1, len(self.text))
        if "\0" in value or len(value.encode("utf-8")) > 4095:
            raise RuntimeFailure(token, "입력 한 줄은 NUL 없이 UTF-8 4095바이트까지 가능합니다.")
        return value

    async def string(self, token):
        if self.pending:
            raise RuntimeFailure(token, "같은 줄에 아직 읽지 않은 숫자가 있습니다. 숫자를 모두 읽은 뒤 다음 줄에서 문자열을 입력하세요.")
        return await self.line(token)

    async def number(self, kind, token):
        while not self.pending:
            self.pending = (await self.line(token)).strip(SPACE)
        match = re.match(r"[^ \t\r\n\v\f]+", self.pending)
        value = match.group()
        self.pending = self.pending[match.end():].lstrip(SPACE)
        pattern = r"[+-]?[0-9]+" if kind == "int" else r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?"
        if not re.fullmatch(pattern, value):
            raise RuntimeFailure(token, "올바른 정수를 입력하세요." if kind == "int" else "올바른 실수를 입력하세요.")
        if kind == "int":
            # Bound conversion work even on runtimes with relaxed int digit limits.
            digits = value.lstrip("+-").lstrip("0")
            if len(digits) > 19:
                raise RuntimeFailure(token, "정수 입력이 64비트 범위를 벗어났습니다.")
            result = int(value)
            if not MIN_INT <= result <= MAX_INT:
                raise RuntimeFailure(token, "정수 입력이 64비트 범위를 벗어났습니다.")
            return result
        result = float(value)
        # strtod reports ERANGE for underflow, including inexact subnormals.
        exact = Decimal(value)
        if (not math.isfinite(result) or
                (exact != 0 and (result == 0 or
                 (abs(result) < float.fromhex("0x1p-1022") and Decimal.from_float(result) != exact)))):
            raise RuntimeFailure(token, "실수 입력이 표현 가능한 범위를 벗어났습니다.")
        return result


class Interpreter:
    def __init__(self, program, stdin, emit=None, provider=None):
        self.program = program
        self.functions = {f.binding: f for f in program.functions}
        self.input = Input(stdin, provider)
        self.output, self.output_size = [], 0
        self.steps, self.array_items = 0, 0
        self.emit = emit

    def tick(self, token):
        self.steps += 1
        if self.steps > MAX_STEPS:
            raise RuntimeFailure(token, "웹 실행기의 연산 한도를 초과했습니다.")

    def convert(self, value, kind, token):
        if kind == "real":
            return float(value)
        if kind == "int" and isinstance(value, float):
            if not math.isfinite(value) or value < MIN_INT or value >= 2 ** 63:
                raise RuntimeFailure(token, "실수를 정수로 변환할 수 있는 범위를 벗어났습니다.")
            return int(value)
        return value

    async def address(self, expr, env):
        if expr.kind == "variable":
            return env, expr.binding
        index = await self.expression(expr.left, env)
        data = env[expr.binding]
        if index < 0 or index >= len(data):
            raise RuntimeFailure(expr.token, "배열 인덱스가 범위를 벗어났습니다.")
        return data, index

    async def expression(self, expr, env):
        self.tick(expr.token)
        kind = expr.kind
        if kind == "literal":
            return expr.value if expr.type == "string" else (int(expr.value) if expr.type == "int" else float(expr.value))
        if kind in ("variable", "remaining"):
            return env[expr.binding]
        if kind == "index":
            container, key = await self.address(expr, env)
            return container[key]
        if kind == "call":
            values = [self.convert(await self.expression(a, env), t, a.token) for a, t in zip(expr.args, expr.arg_types)]
            return await self.function(self.functions[expr.binding], values)
        if kind == "stringify":
            value = await self.expression(expr.left, env)
            return format(value, ".15g") if expr.left.type == "real" else str(value)
        left = await self.expression(expr.left, env)
        right = await self.expression(expr.right, env)
        if expr.value == "CONCAT":
            value = left + right
            if len(value.encode("utf-8")) > 4095:
                raise RuntimeFailure(expr.token, "문자열은 UTF-8 4095바이트까지 지원합니다.")
            return value
        if expr.type == "real":
            left, right = float(left), float(right)
        if expr.value in ("DIV", "MOD"):
            if right == 0:
                raise RuntimeFailure(expr.token, "0으로 나눌 수 없습니다.")
            if expr.type == "int" and left == MIN_INT and right == -1:
                raise RuntimeFailure(expr.token, "정수 계산이 64비트 범위를 벗어났습니다.")
        if expr.value == "ADD":
            value = left + right
        elif expr.value == "SUB":
            value = left - right
        elif expr.value == "MUL":
            value = left * right
        elif expr.type == "real":
            value = left / right
        else:
            quotient = (abs(left) // abs(right)) * (-1 if (left < 0) != (right < 0) else 1)
            value = quotient if expr.value == "DIV" else left - quotient * right
        if expr.type == "int" and not MIN_INT <= value <= MAX_INT:
            raise RuntimeFailure(expr.token, "정수 계산이 64비트 범위를 벗어났습니다.")
        if expr.type == "real" and not math.isfinite(value):
            raise RuntimeFailure(expr.token, "실수 계산 결과가 유한한 범위를 벗어났습니다.")
        return value

    async def scoped(self, statements, env):
        # Binding IDs are unique. Remove only this scope's declarations; outer
        # variable/array assignments survive, including break/continue paths.
        bindings = [s.binding for s in statements if s.kind in ("declare", "array_declare")]
        try:
            await self.statements(statements, env)
        finally:
            for binding in bindings:
                value = env.pop(binding, None)
                if isinstance(value, array):
                    self.array_items -= len(value)

    async def statements(self, statements, env):
        for s in statements:
            self.tick(s.token)
            kind = s.kind
            if kind == "declare":
                env[s.binding] = self.convert(await self.expression(s.expr, env), s.type, s.expr.token)
            elif kind == "array_declare":
                size = await self.expression(s.expr, env)
                if size < 0:
                    raise RuntimeFailure(s.token, "배열 크기는 음수일 수 없습니다.")
                if size > MAX_ARRAY_ITEMS - self.array_items:
                    raise RuntimeFailure(s.token, "웹 실행기는 동시에 총 1,000,000개의 배열 원소까지 지원합니다.")
                env[s.binding] = array("q", [0]) * size
                self.array_items += size
            elif kind == "assign":
                container, key = await self.address(s.target, env)
                container[key] = self.convert(await self.expression(s.expr, env), s.type, s.expr.token)
            elif kind == "input":
                container, key = await self.address(s.target, env)
                container[key] = await self.input.string(s.token)
            elif kind == "number_input":
                for target in s.targets:
                    container, key = await self.address(target, env)
                    container[key] = await self.input.number(target.type, s.token)
            elif kind == "output":
                value = await self.expression(s.expr, env)
                text = (format(value, ".15g") if s.expr.type == "real" else str(value)) + ("\n" if s.newline else "")
                self.output_size += len(text.encode("utf-8"))
                if self.output_size > MAX_OUTPUT:
                    raise RuntimeFailure(s.token, "출력이 웹 실행기의 64 KiB 한도를 초과했습니다.")
                self.output.append(text)
                if self.emit:
                    self.emit(text)
            elif kind == "call":
                await self.expression(s.expr, env)
            elif kind == "block":
                await self.scoped(s.body, env)
            elif kind == "sign":
                value = await self.expression(s.expr, env)
                reaction = "POSITIVE" if value > 0 else "NEGATIVE" if value < 0 else "ZERO"
                for branch in s.branches:
                    if branch.token.kind == reaction:
                        await self.scoped(branch.body, env)
                        break
            elif kind == "count":
                count = await self.expression(s.expr, env)
                if count < 0:
                    raise RuntimeFailure(s.token, "반복 횟수는 음수일 수 없습니다.")
                try:
                    while count > 0:
                        self.tick(s.token)
                        env[s.binding] = count
                        try:
                            await self.scoped(s.body, env)
                        except LoopContinue:
                            pass
                        except LoopBreak:
                            break
                        count -= 1
                finally:
                    env.pop(s.binding, None)
            elif kind == "repeat":
                while True:
                    self.tick(s.token)
                    try:
                        await self.scoped(s.body, env)
                    except LoopContinue:
                        pass
                    except LoopBreak:
                        break
                    if await self.expression(s.expr, env) <= 0:
                        break
            elif kind == "break":
                raise LoopBreak()
            elif kind == "continue":
                raise LoopContinue()

    async def function(self, function, values=()):
        env = {p.binding: v for p, v in zip(function.params, values)}
        try:
            await self.statements(function.body, env)
            return await self.expression(function.result, env) if function.result else 0
        finally:
            for value in env.values():
                if isinstance(value, array):
                    self.array_items -= len(value)


async def execute_async(source, stdin="", emit=None, provider=None):
    engine = None
    try:
        if len(source.encode("utf-8")) > MAX_SOURCE or len(stdin.encode("utf-8")) > MAX_INPUT:
            return {"stdout": "", "stderr": "웹 실행기 한도: 코드 256 KiB, 입력 1 MiB입니다.", "exitCode": 2}
        source = source.removeprefix("\ufeff")
        program = Parser(lex(source)).parse()
        analyze(program)
        engine = Interpreter(program, stdin, emit, provider)
        await engine.function(program.main)
        return {"stdout": "".join(engine.output), "stderr": "", "exitCode": 0}
    except CompileError as error:
        message = error.format("main.usagi", source)
    except RuntimeFailure as error:
        message = f"main.usagi:{error.token.line}:{error.token.column}: 실행 오류: {error.message}"
    except (RecursionError, MemoryError):
        message = "프로그램이 웹 실행기의 메모리 또는 식 중첩 한도를 초과했습니다."
    except (ValueError, InvalidOperation, OverflowError):
        message = "표현할 수 없는 숫자 입력 또는 계산 결과입니다."
    return {"stdout": "".join(engine.output) if engine else "", "stderr": message, "exitCode": 2}


def execute(source, stdin="", emit=None):
    """Synchronous entry point for native conformance/unit tests."""
    return asyncio.run(execute_async(source, stdin, emit))


async def run_json_async(source, stdin="", emit=None, provider=None):
    return json.dumps(await execute_async(source, stdin, emit, provider), ensure_ascii=False)
